"""
Page 2 - Accident Hotspot Heatmap
DBSCAN clustering visualization using Plotly density_mapbox
"""
import streamlit as st
import pandas as pd
import numpy as np
import plotly.express as px
import plotly.graph_objects as go

st.set_page_config(page_title="Hotspot Map | Road Safety AI", page_icon="🗺️", layout="wide")

st.title("🗺️ Accident Hotspot Heatmap")
st.caption(
    "Accident-prone zones identified by **DBSCAN clustering** on historical accident data. "
    "Generated by the **Hotspot Detection Agent** (IBM watsonx Granite-3)."
)

# ── Controls ──────────────────────────────────────────────────────────────────
with st.expander("🔧 Filter Settings", expanded=True):
    col1, col2, col3 = st.columns(3)
    with col1:
        radius_km = st.slider("Cluster Radius (km)", 0.5, 5.0, 1.0, 0.5)
    with col2:
        min_incidents = st.slider("Min Incidents per Cluster", 2, 20, 3)
    with col3:
        risk_filter = st.multiselect(
            "Risk Levels to Show",
            ["CRITICAL", "HIGH", "MEDIUM", "LOW"],
            default=["CRITICAL", "HIGH", "MEDIUM", "LOW"],
        )

# ── Generate synthetic hotspot clusters ──────────────────────────────────────
np.random.seed(7)
BASE_LAT, BASE_LNG = 51.5074, -0.1278

# Simulate DBSCAN output clusters
clusters = []
cluster_configs = [
    (51.515, -0.120, "CRITICAL", 28, 9.5),
    (51.508, -0.098, "HIGH", 18, 7.2),
    (51.522, -0.140, "HIGH", 15, 6.8),
    (51.500, -0.115, "MEDIUM", 9, 5.1),
    (51.530, -0.108, "MEDIUM", 11, 4.9),
    (51.495, -0.132, "LOW", 5, 3.2),
    (51.512, -0.155, "CRITICAL", 31, 10.0),
    (51.488, -0.105, "HIGH", 22, 8.1),
    (51.525, -0.127, "MEDIUM", 8, 4.4),
    (51.505, -0.145, "LOW", 4, 2.8),
]
for lat, lng, level, count, score in cluster_configs:
    # Add slight jitter per radius
    lat_j = lat + np.random.uniform(-0.003, 0.003)
    lng_j = lng + np.random.uniform(-0.003, 0.003)
    if level in risk_filter and count >= min_incidents:
        clusters.append({
            "lat": round(lat_j, 6), "lng": round(lng_j, 6),
            "risk_level": level, "incident_count": count,
            "risk_score": score, "radius_m": radius_km * 1000,
        })

# Generate individual accident points around clusters for heatmap
accident_points = []
for c in clusters:
    for _ in range(c["incident_count"]):
        accident_points.append({
            "lat": c["lat"] + np.random.uniform(-0.005, 0.005),
            "lng": c["lng"] + np.random.uniform(-0.005, 0.005),
            "weight": c["risk_score"] / 10,
        })

df_pts = pd.DataFrame(accident_points) if accident_points else pd.DataFrame(
    {"lat": [51.5074], "lng": [-0.1278], "weight": [1.0]}
)
df_clusters = pd.DataFrame(clusters) if clusters else pd.DataFrame()

# ── Heatmap ───────────────────────────────────────────────────────────────────
st.subheader("🔥 Accident Density Heatmap")

color_map = {
    "CRITICAL": "#dc2626", "HIGH": "#ea580c", "MEDIUM": "#d97706", "LOW": "#16a34a"
}

fig_heat = px.density_mapbox(
    df_pts, lat="lat", lon="lng", z="weight",
    radius=30, center={"lat": BASE_LAT, "lon": BASE_LNG},
    zoom=11, mapbox_style="open-street-map",
    color_continuous_scale=["#16a34a", "#d97706", "#ea580c", "#dc2626"],
    height=500,
    title="Accident Density — Historical Data (DBSCAN Clustering)",
)

# Overlay cluster markers
if not df_clusters.empty:
    for _, c in df_clusters.iterrows():
        fig_heat.add_trace(go.Scattermapbox(
            lat=[c["lat"]], lon=[c["lng"]],
            mode="markers+text",
            marker=dict(size=14 + c["incident_count"] / 3,
                        color=color_map.get(c["risk_level"], "#6b7280"),
                        opacity=0.85),
            text=[f"{c['risk_level']} ({c['incident_count']} incidents)"],
            textposition="top center",
            name=c["risk_level"],
            showlegend=False,
        ))

fig_heat.update_layout(margin=dict(t=40, b=0))
st.plotly_chart(fig_heat, use_container_width=True)

# ── Cluster Table ─────────────────────────────────────────────────────────────
st.subheader("📋 Detected Hotspot Clusters")
st.caption(f"Showing {len(clusters)} clusters | Model: DBSCAN (eps={radius_km}km) + watsonx Granite analysis")

if not df_clusters.empty:
    display_df = df_clusters.copy()
    display_df.columns = ["Latitude", "Longitude", "Risk Level", "Incident Count",
                           "Risk Score", "Radius (m)"]
    display_df["Risk Score"] = display_df["Risk Score"].apply(lambda x: f"{x:.1f}/10")

    def color_risk(val):
        c = {"CRITICAL": "background-color:#fecaca;font-weight:bold",
             "HIGH": "background-color:#fed7aa;font-weight:bold",
             "MEDIUM": "background-color:#fef3c7",
             "LOW": "background-color:#dcfce7"}
        return c.get(val, "")

    st.dataframe(
        display_df.style.applymap(color_risk, subset=["Risk Level"]),
        use_container_width=True, hide_index=True,
    )

    # Summary by risk level
    st.subheader("📊 Cluster Distribution by Risk Level")
    summary = df_clusters.groupby("risk_level").agg(
        clusters=("lat", "count"),
        total_incidents=("incident_count", "sum"),
    ).reset_index()
    bar_fig = px.bar(summary, x="risk_level", y="total_incidents",
                     color="risk_level",
                     color_discrete_map=color_map,
                     text="total_incidents",
                     labels={"risk_level": "Risk Level", "total_incidents": "Total Incidents"})
    bar_fig.update_layout(height=300, showlegend=False)
    st.plotly_chart(bar_fig, use_container_width=True)

else:
    st.info("No clusters match the current filter settings. Try lowering the minimum incidents.")

st.divider()
st.caption("Hotspots are computed using DBSCAN clustering on historical accident data. This is NOT a real-time feed.")
